class Pharmacy { String pharmacyName,location; static int pharmacyCount; Pharmacy(String pharmacyName,String location){this.pharmacyName=pharmacyName;this.location=location;pharmacyCount++;} void displayPharmacy(){System.out.println(pharmacyName+" - "+location);} static void displayPharmacyCount(){System.out.println("Count: "+pharmacyCount);} }
public class Q03_PharmacyMain { public static void main(String[] a){Pharmacy x=new Pharmacy("Care","Delhi"),y=new Pharmacy("Life","Pune"),z=new Pharmacy("Wellness","Jaipur");x.displayPharmacy();y.displayPharmacy();z.displayPharmacy();Pharmacy.displayPharmacyCount();} }
